theme.css:
#wemd{color:#52525B;background-color:#FFFFFF;font-family:'Inter', 'Segoe UI', -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Noto Sans SC', 'Microsoft YaHei', sans-serif;font-size:15px;line-height:1.8;letter-spacing:0.02em;text-align:justify;padding:40px 16px;overflow-wrap:anywhere}
#wemd p{margin:0 0 1.4em;text-indent:0}
#wemd h1{font-size:26px;font-weight:800;color:#27272A;margin-top:2.4em;margin-bottom:1em;text-align:left}
#wemd h2{font-size:20px;font-weight:800;color:#27272A;margin-top:2.8em;margin-bottom:0.8em;text-align:left;border-bottom:1px solid #E4E4E7;padding-bottom:.4em}
#wemd h3{font-size:16px;font-weight:700;color:#27272A;margin-top:1.8em;margin-bottom:0.6em}
#wemd h4{font-size:15px;font-weight:600;color:#71717A;margin-top:1.4em;margin-bottom:0.5em}
#wemd blockquote{border-left:3px solid #52525B;background:#FAFAFA;padding:14px 20px;color:#52525B;font-style:normal;margin:1.2em 0}
#wemd code{background-color:#F4F4F5;color:#27272A;padding:2px 6px;border-radius:3px;font-size:0.9em;font-family:ui-monospace, 'Cascadia Code', 'Fira Code', Menlo, Monaco, Consolas, monospace}
#wemd pre{background:#FAFAFA;border-radius:4px;padding:16px 20px;line-height:1.5;white-space:pre-wrap}
#wemd pre code{background:transparent;padding:0}
#wemd table{width:100%;border-collapse:collapse}
#wemd th, #wemd td{border:1px solid #E4E4E7;padding:10px 14px}
#wemd th{background:#F4F4F5}
#wemd tr:nth-child(even){background:#FAFAFA}
#wemd ul, #wemd ol{padding-left:24px;margin:1em 0}
#wemd ul{list-style-type:disc}
#wemd ol{list-style-type:decimal}
#wemd li{margin-bottom:8px}
#wemd li::marker{color:#A1A1AA}
#wemd hr{border:0;border-top:1px solid #E4E4E7;margin:3em 0;width:100%}
#wemd img{max-width:100%;height:auto;border-radius:4px}
#wemd figcaption{font-size:12px;color:#A1A1AA;text-align:center}
#wemd a{color:#52525B;text-decoration:underline}
#wemd strong{color:#52525B;font-weight:700}
#wemd mark{background:#F4F4F5;padding:2px 4px;border-radius:2px}
